// Helper function to count valid numbers in arr
function CountValid(arr: seq<int>): int
    requires arr != null
    ensures CountValid(arr) == |{ x | x in arr && 1 <= x <= 9 }|
{
    var count := 0;
    var i := 0;
    while i < |arr|
        invariant 0 <= i <= |arr|
        invariant count == |{ x | j in 0..i-1, x in arr[j..j+1] && 1 <= x <= 9 }|
    {
        if arr[i] >= 1 && arr[i] <= 9 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to reverse and map valid numbers to strings
function ReverseAndMap(arr: seq<int>): seq<string>
    requires arr != null
    ensures |ReverseAndMap(arr)| == CountValid(arr)
{
    var validNumbers := |{ x | x in arr && 1 <= x <= 9 }|;
    var result := new string[validNumbers];
    var index := validNumbers - 1;
    var i := 0;
    while i < |arr|
        invariant 0 <= i <= |arr|
        invariant index + 1 == validNumbers - CountValid(arr[0..i])
    {
        if arr[i] >= 1 && arr[i] <= 9 {
            result[index] := MapToString(arr[i]);
            index := index - 1;
        }
        i := i + 1;
    }
    return result;
}

